            _spot("Charles Darwin Research Station", "Santa Cruz's research centre with a giant-tortoise breeding programme.", "See baby tortoises and learn about conservation.", "morning"),
            _spot("Tortuga Bay", "A white-sand beach reached by a 2.5 km trail with marine iguanas and sharks in the lagoon.", "Swim and spot wildlife.", "morning"),
            _spot("Kicker Rock (Leon Dormido)", "A dramatic volcanic tuff cone off San Cristobal famous for snorkelling with sharks and rays.", "Underwater highlights.", "all year"),
            _spot("Bartolome Island", "A volcanic island with Pinnacle Rock and a summit climb for sweeping views.", "Penguins and lava landscapes.", "sunrise"),
